-- MaNGOS Four EventAI converted to SmartAI for creatures this core leaves unscripted.
-- Source: MaNGOS Four world DB (https://github.com/mangosfour/Database, GPL v3), creature_ai_scripts / creature_ai_texts /
-- creature_ai_summons; meanings from MaNGOS Four's CreatureEventAI.h/.cpp (Copyright (C) 2005-2026 MaNGOS <https://www.getmangos.eu>).
-- 967 creatures, 2468 SmartAI rows, 376 text lines. Generator: skyfire_port_plan/tools/dbcompare/m4_eventai.py.
-- Safe to run twice: a creature's rows are only added while it still has no SmartAI rows.

DROP TEMPORARY TABLE IF EXISTS `tmp_m4_smart`;
CREATE TEMPORARY TABLE `tmp_m4_smart` LIKE `smart_scripts`;
DELETE t FROM `tmp_m4_smart` t JOIN (SELECT DISTINCT `entryorguid`, `source_type` FROM `smart_scripts`) x ON x.`entryorguid` = t.`entryorguid` AND x.`source_type` = t.`source_type`;
-- Texts: only for the creatures whose rows go in now
DROP TEMPORARY TABLE IF EXISTS `tmp_m4_text`;
CREATE TEMPORARY TABLE `tmp_m4_text` LIKE `creature_text`;
DELETE t FROM `tmp_m4_text` t WHERE t.`entry` NOT IN (SELECT DISTINCT `entryorguid` FROM `tmp_m4_smart`);
DROP TEMPORARY TABLE `tmp_m4_smart`;
DROP TEMPORARY TABLE `tmp_m4_text`;

